class Cat {
    String name;
    String cry;

    Cat(String name, String cry) {
        this.name = name;
        this.cry = cry;
    }

    static String whoAmI(String name, String cry) {
        return "我是 " + name + "，叫声是 " + cry;
    }
}

public class Main {
    public static void main(String[] args) {
        Cat a = new Cat("{cat}", "{cry}");
        System.out.println(Cat.whoAmI(a.name, a.cry));
    }
}
